def is_permutation_mod_p(a3, a1, p):
    """Checks if P(x) = a3*x^3 + a1*x is a permutation polynomial modulo p."""
    residues = set()
    for x in range(p):
        # Calculate P(x) mod p
        Px = (a3 * (x**3) + a1 * x) % p

        # Check if Px has already been seen
        if Px in residues:
            return False
        residues.add(Px)

    # If we have generated p distinct residues, it is a permutation
    return len(residues) == p

P = 11
successful_pairs = []

# Iterate over all possible values for a3 mod 11 and a1 mod 11
for a3_prime in range(P):
    for a1_prime in range(P):
        if is_permutation_mod_p(a3_prime, a1_prime, P):
            successful_pairs.append((a3_prime, a1_prime))

print("Successful (a3 mod 11, a1 mod 11) pairs:")
for pair in successful_pairs:
    print(pair)

print(f"\nTotal number of solutions: {len(successful_pairs)}")
